<?php require_once 'app.php';require_login();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=db()->prepare('INSERT INTO investimentos(usuario_id,ativo,data_aporte,valor,rentabilidade,observacoes) VALUES(?,?,?,?,?,?)');$s->execute([user()['id'],post('ativo'),post('data')?:date('Y-m-d'),str_replace(',','.',post('valor')),str_replace(',','.',post('rentabilidade')?:'0'),post('observacoes')]);flash('success','Investimento registrado.');redirect('controle_investimentos.php');}$s=db()->prepare('SELECT * FROM investimentos WHERE usuario_id=? ORDER BY data_aporte DESC');$s->execute([user()['id']]);$rows=$s->fetchAll();layout_start('Investimentos');?><div class="card p-4 mb-4"><form method="post" class="row g-2"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="col-md-3"><input class="form-control" name="ativo" placeholder="Ativo / aplicação" required></div><div class="col-md-2"><input class="form-control" type="date" name="data" value="<?=date('Y-m-d')?>" required></div><div class="col-md-2"><input class="form-control" type="number" step=".01" name="valor" placeholder="Aporte" required></div><div class="col-md-2"><input class="form-control" type="number" step=".01" name="rentabilidade" placeholder="% rentabilidade"></div><div class="col-md-3"><button class="btn btn-primary w-100">Adicionar</button></div></form></div><div class="card p-3 table-responsive"><table class="table"><tr><th>Ativo</th><th>Data</th><th>Valor</th><th>Rentabilidade</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['ativo'])?></td><td><?=date('d/m/Y',strtotime($r['data_aporte']))?></td><td><?=money($r['valor'])?></td><td><?=e($r['rentabilidade'])?>%</td></tr><?php endforeach;?></table></div><?php layout_end();